import BottomSheet, {
	BottomSheetBackdrop,
	BottomSheetBackdropProps,
	BottomSheetView
} from '@gorhom/bottom-sheet'
import { Trash2 } from 'lucide-react-native'
import { LayoutChangeEvent, Text, View } from 'react-native'
import { colors, Theme, useTheme } from '@/theme'
import { useState } from 'react'
import { defineStyles } from '@/utils/defineStyles'
import { Gesture, GestureDetector } from 'react-native-gesture-handler'
import Animated, {
	runOnJS,
	useAnimatedStyle,
	useSharedValue,
	withSpring
} from 'react-native-reanimated'
import * as Haptics from 'expo-haptics'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { useDeleteUserMutation } from '@/generated/graphql'
import { useMe } from '@/utils/hooks/useMe'
import { toast } from '@/utils/toast'

const THUMB_SIZE = 64
const SLIDE_PADDING = 6

const SwipeToDelete = ({ onDelete }: { onDelete: () => Promise<void> }) => {
	const { theme } = useTheme()
	const translateX = useSharedValue(0)
	const [sliderWidth, setSliderWidth] = useState(0)
	const COMPLETION_THRESHOLD = 0.95

	const handleLayout = (event: LayoutChangeEvent) => {
		setSliderWidth(event.nativeEvent.layout.width)
	}

	const triggerDelete = async () => {
		Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success)
		await onDelete()
	}

	const panGesture = Gesture.Pan()
		.onChange((event) => {
			const maxTranslate = sliderWidth - THUMB_SIZE
			translateX.value = Math.max(0, Math.min(maxTranslate, event.translationX))
		})
		.onEnd(() => {
			const maxTranslate = sliderWidth - THUMB_SIZE
			const progress = translateX.value / maxTranslate

			if (progress >= COMPLETION_THRESHOLD) {
				translateX.value = withSpring(maxTranslate, { damping: 100 })
				runOnJS(triggerDelete)()
			} else {
				translateX.value = withSpring(0, { damping: 100 })
			}
		})

	const thumbStyle = useAnimatedStyle(() => ({
		transform: [{ translateX: translateX.value }]
	}))

	const textStyle = useAnimatedStyle(() => {
		const maxTranslate = sliderWidth - THUMB_SIZE
		const progress = maxTranslate > 0 ? translateX.value / maxTranslate : 0

		return {
			opacity: 1 - progress * 0.5
		}
	})

	return (
		<View style={styles.sliderContainer} onLayout={handleLayout}>
			<Animated.View style={[styles.sliderBackground(theme)]}>
				<Animated.Text style={[styles.sliderText(theme), textStyle]}>
					Slide to delete account
				</Animated.Text>
			</Animated.View>
			<GestureDetector gesture={panGesture}>
				<Animated.View style={[styles.sliderThumb(theme), thumbStyle]}>
					<Trash2 size={20} color={colors.dark.gray[900]} />
				</Animated.View>
			</GestureDetector>
		</View>
	)
}

export const DeleteAccountBottomSheet = ({
	sliderKey,
	bottomSheetRef,
	handleLogout
}: {
	sliderKey: number
	bottomSheetRef: React.RefObject<BottomSheet | null>
	handleLogout: () => void
}) => {
	const { me } = useMe()
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()
	const [deleteUser] = useDeleteUserMutation()

	const renderBackdrop = (props: BottomSheetBackdropProps) => (
		<BottomSheetBackdrop
			{...props}
			opacity={0.8}
			disappearsOnIndex={-1}
			appearsOnIndex={0}
		/>
	)

	const handleCloseSheet = () => {
		bottomSheetRef.current?.close()
	}

	const handleDeleteAccount = async () => {
		handleCloseSheet()
		if (!me) {
			toast.show({
				variant: 'error',
				message: 'Error deleting account'
			})
			return
		}
		try {
			const { data } = await deleteUser({
				variables: { input: { userId: me.id } }
			})
			if (data?.deleteUser?.success) {
				handleLogout()
				toast.show({
					variant: 'success',
					message: 'Account deleted successfully'
				})
			}
		} catch (error) {
			console.error('Error deleting user:', error)
			toast.show({
				variant: 'error',
				message: 'Error deleting account'
			})
		}
	}

	return (
		<BottomSheet
			ref={bottomSheetRef}
			backgroundStyle={styles.bottomSheetBackground(theme)}
			backdropComponent={renderBackdrop}
			index={-1}
			enablePanDownToClose
			handleIndicatorStyle={styles.bottomSheetIndicator(theme)}
		>
			<BottomSheetView
				style={[styles.bottomSheetContent, { paddingBottom: insets.bottom }]}
			>
				<View style={styles.bottomSheetHeader}>
					<Text style={styles.bottomSheetTitle(theme)}>Are you sure?</Text>
				</View>

				<View style={styles.bottomSheetBody}>
					<Text style={styles.bottomSheetMessage(theme)}>
						This action is irreversible and will result in losing your account
						and live or unpublished projects
					</Text>
				</View>

				<SwipeToDelete key={sliderKey} onDelete={handleDeleteAccount} />
			</BottomSheetView>
		</BottomSheet>
	)
}

const styles = defineStyles({
	bottomSheetBackground: (theme: Theme) => ({
		backgroundColor: colors[theme].background
	}),
	bottomSheetContent: {
		paddingTop: 12,
		paddingBottom: 24,
		paddingHorizontal: 24,
		borderRadius: 24,
		gap: 20
	},
	bottomSheetIndicator: (theme: Theme) => ({
		backgroundColor: colors[theme].gray[400],
		width: 64
	}),
	bottomSheetHeader: {},
	bottomSheetTitle: (theme: Theme) => ({
		fontSize: 18,
		fontWeight: '500',
		color: colors[theme].gray[900],
		textAlign: 'center'
	}),
	bottomSheetBody: {
		gap: 12
	},
	bottomSheetMessage: (theme: Theme) => ({
		fontSize: 16,
		lineHeight: 24,
		color: colors[theme].gray[400],
		textAlign: 'center'
	}),
	sliderContainer: {
		height: THUMB_SIZE,
		position: 'relative',
		width: '100%'
	},
	sliderBackground: (theme: Theme) => ({
		height: THUMB_SIZE,
		borderRadius: 100,
		backgroundColor: `${colors[theme].red[300]}1A`,
		justifyContent: 'center',
		alignItems: 'center',
		overflow: 'hidden'
	}),
	sliderText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '600',
		color: colors[theme].red[400]
	}),
	sliderThumb: (theme: Theme) => ({
		position: 'absolute',
		top: SLIDE_PADDING,
		left: SLIDE_PADDING,
		width: THUMB_SIZE - SLIDE_PADDING * 2,
		height: THUMB_SIZE - SLIDE_PADDING * 2,
		borderRadius: 100,
		backgroundColor: colors[theme].red[300],
		justifyContent: 'center',
		alignItems: 'center'
	})
})
